aligned(8) class ICCProfileHeader {
	unsigned int(32) profile_size;
	unsigned int(32) preferred_cmm_type;
	unsigned int(8) profile_version_major;
	unsigned int(4) profile_version_minor;
	unsigned int(4) profile_version_bugfix;
	unsigned int(16) reserved = 0;
	unsigned int(32) profile_device_class;	// 'scnr', 'mntr', 'prtr', 'link', 'spac', 'abst', 'nmcl'
	unsigned int(32) colour_space;	// 'XYZ ', 'Lab ', 'RGB ', 'GRAY', 'CMYK'...
	unsigned int(32) profile_connection_space;	// 'XYZ ', 'Lab '
	unsigned int(16) year;
	unsigned int(16) month;
	unsigned int(16) day;
	unsigned int(16) hours;
	unsigned int(16) minutes;
	unsigned int(16) seconds;
	unsigned int(32) profile_file_signature;	// 'acsp'
	unsigned int(32) primary_platform;	// 'APPL', 'MSFT', 'SGI ', 'SUNW'
	unsigned int(32) profile_flags;
	unsigned int(32) device_manufacturer;
	unsigned int(32) device_model;
	unsigned int(64) device_attributes;
	unsigned int(32) rendering_intent;
	signed int(32) pcs_illuminant_x;	// s15Fixed16Number
	signed int(32) pcs_illuminant_y;
	signed int(32) pcs_illuminant_z;
	unsigned int(32) profile_creator;
	unsigned int(8) profile_id[16];	// MD5
	unsigned int(8) reserved[28];
}

aligned(8) class ICCTagEntry {
	unsigned int(32) tag_signature;	// 'desc', 'cprt', 'wtpt', 'rXYZ', 'rTRC'...
	unsigned int(32) offset;	// of the tag's element, from the start of the profile
	unsigned int(32) size;	// of the tag's element
}

aligned(8) class ICCXYZType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	ICCXYZNumber values[];	// to the end of the element
}
aligned(8) class ICCXYZNumber() {
	signed int(32) x;	// s15Fixed16Number
	signed int(32) y;
	signed int(32) z;
}

aligned(8) class ICCCurveType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(32) entry_count;
	if (entry_count == 1) {
		unsigned int(16) gamma;	// u8Fixed8Number
	} else {
		unsigned int(16) curve[entry_count];
	}
}

aligned(8) class ICCParametricCurveType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(16) function_type;
	unsigned int(16) reserved = 0;
	signed int(32) parameters[];	// s15Fixed16Number: g; g a b; g a b c; g a b c d; g a b c d e f
}

aligned(8) class ICCS15Fixed16ArrayType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	signed int(32) values[];	// s15Fixed16Number, to the end of the element
}

aligned(8) class ICCTextType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	bytestring text;	// 7-bit ASCII, of a terminating null: all that is left, as bytes
}

aligned(8) class ICCTextDescriptionType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(32) ascii_count;
	bytestring ascii[ascii_count];	// 7-bit ASCII, of a terminating null
	unsigned int(32) unicode_language;
	unsigned int(32) unicode_count;
	utf16string unicode[unicode_count];	// UTF-16BE, of a terminating null
	unsigned int(16) scriptcode_code;
	unsigned int(8) scriptcode_count;
	unsigned int(8) scriptcode[67];
}

aligned(8) class ICCMultiLocalizedUnicodeType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(32) record_count;
	unsigned int(32) record_size;	// 12
	for (i = 0; i < record_count; i++) {
		unsigned int(16) language;	// ISO 639-1
		unsigned int(16) country;	// ISO 3166-1
		unsigned int(32) length;
		unsigned int(32) offset;	// of its string, from the start of the element
	}
	utf16string strings;	// UTF-16BE, each record's at its offset: all that is left
}

aligned(8) class ICCSignatureType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(32) signature;
}

aligned(8) class ICCCicpType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(8) colour_primaries;
	unsigned int(8) transfer_characteristics;
	unsigned int(8) matrix_coefficients;
	unsigned int(8) video_full_range_flag;
}

aligned(8) class ICCChromaticityType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(16) channel_count;
	unsigned int(16) phosphor_or_colorant_type;
	for (i = 0; i < channel_count; i++) {
		unsigned int(32) x;	// u16Fixed16Number
		unsigned int(32) y;
	}
}

aligned(8) class ICCMeasurementType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	unsigned int(32) standard_observer;	// 1: CIE 1931, 2: CIE 1964
	ICCXYZNumber backing;	// the tristimulus values of the measurement backing
	unsigned int(32) geometry;
	unsigned int(32) flare;	// u16Fixed16Number
	unsigned int(32) illuminant;	// 1: D50, 2: D65, 3: D93, 4: F2, 5: D55, 6: A, 7: E, 8: F8
}

aligned(8) class ICCViewingConditionsType {
	unsigned int(32) type_signature;
	unsigned int(32) reserved = 0;
	ICCXYZNumber illuminant;	// in cd/m2
	ICCXYZNumber surround;	// in cd/m2
	unsigned int(32) illuminant_type;
}
